# Human factors, spatial disorientation and risk management for IFR: Instrument Flying Handbook
# FAA-H-8083-15B ch. 3 (illusions, ADM), Risk Management Handbook FAA-H-8083-2A, AIM 8-1. ACS I.A.R,
# I.C.R, II.B.R, Appendix 2 (ADM, SRM).
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Vestibular illusions", "You enter a bank too slowly to sense, then level the wings abruptly and feel banked the other way. What is this?",
      ["The leans", "Inversion illusion", "Elevator illusion"],
      "The Instrument Flying Handbook describes the leans: a slow bank goes unnoticed, and an abrupt correction makes the semicircular canals report a bank the other way."),
    S(1, 2, "Visual illusions", "On a night approach over dark water or terrain with no lights, what is the usual error?",
      ["Flying lower than intended", "Flying higher than intended", "Landing long and fast"],
      "A featureless dark area before the runway makes pilots feel higher than they are, the black hole approach, so they tend to fly a low approach."),
    S(1, 2, "Personal minimums", "Why set personal minimums above the legal approach minimums?",
      ["To keep a margin for your own skill", "Because legal minimums are advisory", "To let ATC give you priority"],
      "Legal minimums assume a proficient pilot. Personal minimums, set on the ground, add a margin that matches your recent experience, the airplane and the conditions."),
    S(1, 3, "Proficiency and currency", "A pilot meets 61.57 currency entirely with approaches in clear skies. What risk remains?",
      ["Current but not proficient in IMC", "Losing the instrument rating itself", "Needing a new medical certificate"],
      "The ACS lists proficiency versus currency as a risk element. Meeting the minimum tasks doesn't guarantee skill in real cloud, turbulence and workload."),
    S(1, 2, "Automation", "In IMC the autopilot begins a turn you didn't expect. What should you do first?",
      ["Disconnect it and hand-fly", "Reprogram the flight plan at once", "Wait to see where it is going"],
      "When automation does something unexpected, fly the airplane first: disconnect, hand-fly to a safe attitude and heading, then sort out the modes."),
    S(1, 3, "Hazardous attitudes", "\"I've flown approaches lower than this; watch me get in.\" Which hazardous attitude, and what antidote?",
      ["Macho; taking chances is foolish", "Invulnerability; it could happen to me", "Impulsivity; not so fast, think first"],
      "Trying to prove oneself by taking risks is the macho attitude. The antidote is 'Taking chances is foolish.'"),
    # ---------- Practice Test 2 ----------
    S(2, 2, "Vestibular illusions", "After an abrupt level-off from a climb, you feel you are tumbling backward. What is the danger?",
      ["Pushing the nose too low", "Pulling into a steep climb", "Rolling into a steep bank"],
      "The inversion illusion follows an abrupt change from climb to level flight. The disoriented pilot may push the nose down abruptly, making the illusion worse."),
    S(2, 3, "Vestibular illusions", "A sudden updraft in cloud makes you feel you are climbing. What may you do wrongly?",
      ["Lower the nose into a dive", "Pull the airplane into a stall", "Roll into a steep bank"],
      "An abrupt upward acceleration stimulates the otolith organs and creates the elevator illusion of climbing, so a pilot may push the nose down. A downdraft has the opposite effect."),
    S(2, 2, "Visual illusions", "Breaking out on an approach to an upsloping runway, what illusion is likely?",
      ["Feeling too high, so flying low", "Feeling too low, so flying high", "Feeling too fast, so slowing"],
      "An upsloping runway looks like a steeper approach, so the pilot feels high and tends to fly lower than the correct glidepath."),
    S(2, 2, "Decision models", "In the DECIDE model, what comes right after Detect?",
      ["Estimate", "Choose", "Evaluate"],
      "DECIDE is Detect a change, Estimate the need to react, Choose a desirable outcome, Identify actions, Do the best action and Evaluate the effect."),
    S(2, 3, "Hazardous attitudes", "\"Ice won't build on us, it never does.\" Which antidote fits?",
      ["It could happen to me", "Follow the rules; they are usually right", "I'm not helpless; I can make a difference"],
      "Believing accidents happen only to others is the invulnerability attitude. Its antidote is 'It could happen to me.'"),
    S(2, 2, "External pressures", "How can you guard against pressing on into worsening weather to keep a schedule?",
      ["Set a divert point before departure", "Leave the alternate off the flight plan", "Plan only the most direct route"],
      "External pressures drive plan-continuation errors. Deciding the divert criteria and alternates on the ground makes the decision easier in flight."),
    # ---------- Drill only ----------
    S(0, 2, "Vestibular system", "Which part of the inner ear senses angular acceleration?",
      ["Semicircular canals", "Otolith organs", "Eardrum"],
      "The semicircular canals sense angular acceleration in pitch, roll and yaw. The otolith organs sense linear acceleration and gravity."),
    S(0, 3, "Vestibular system", "Why can't you feel a constant-rate turn held for a long time?",
      ["The canal fluid stops moving", "The otoliths tire after one minute", "Bank angle can't be sensed at all"],
      "In a sustained constant-rate turn the fluid in the semicircular canals reaches the canal's speed, so no motion is sensed, which sets up the graveyard spiral and Coriolis illusion."),
    S(0, 2, "Visual illusions", "At night, a single light stared at for some seconds seems to move. What is this?",
      ["Autokinesis", "False horizon", "Flicker vertigo"],
      "Autokinesis makes a stationary light appear to move in the dark. Keep scanning and refer to the instruments."),
    S(0, 2, "Visual illusions", "Sloping cloud tops can lead you to roll the wings to match them. This is:",
      ["A false horizon", "Autokinesis", "The leans"],
      "A sloping cloud bank, an obscured horizon or patterns of ground lights can give a false horizon. Trust the attitude indicator."),
    S(0, 2, "Risk assessment", "In the FAA's risk matrix, which two factors set a hazard's risk?",
      ["Likelihood and severity", "Altitude and airspeed", "Fuel load and distance flown"],
      "The Risk Management Handbook assesses risk by the likelihood of an event and the severity of its outcome, from which a risk level follows."),
    S(0, 2, "Automation", "After selecting an autopilot mode, what guards against mode confusion?",
      ["Confirm it on the annunciator", "Look at the moving map only", "Wait for ATC to point out errors"],
      "Check the mode annunciator after every selection to confirm the autopilot is doing what you asked, and be ready to hand-fly if it isn't."),
    S(0, 2, "Using resources", "Overloaded in IMC, how can single-pilot resource management help?",
      ["Ask ATC for a delay or vectors", "Turn off the autopilot to stay busy", "Stop talking to ATC until things settle"],
      "SRM means using every resource. ATC can give holding, delay vectors or a different approach to reduce workload."),
    S(0, 2, "Fitness for flight", "Why check an over-the-counter cold medicine before an IFR flight?",
      ["Many cause drowsiness", "They lower your blood alcohol limit", "They make the altimeter misread"],
      "Many antihistamines and decongestants cause drowsiness or impaired judgment, which is dangerous in IMC. The IMSAFE check covers medication."),
    S(0, 3, "Night vision", "According to the AIM, above about what altitude does lack of oxygen begin to dim night vision?",
      ["5,000 feet", "10,000 feet", "12,500 feet"],
      "AIM 8-1-2 notes that night vision can be significantly reduced from as low as 5,000 feet without supplemental oxygen."),
]
